import Header from '../components/Header';
import Footer from '../components/Footer';
import React from 'react';
import '../styles/PDF.css';

function Partitions() {
    return (
        <div>
            <Header />
            <h1>Partitions</h1>
            {<PdfViewer />}
            <Footer />
        </div>
    )
}


function PdfViewer() {
    return (
        <div className="pdf-container">
            <iframe
                src="/documents/game_of_throne.pdf"
                width="100%"
                height="600px"
                title="PDF"
                style={{ border: '2px solid #00ffff', borderRadius: '8px' }}
            />
        </div>
    )
}
export default Partitions;
